"""Rasa A2A ``DefaultRequestHandler`` with ``messageId`` idempotency.

The a2a-sdk ``DefaultRequestHandler`` routes ``message/send`` and
``message/stream`` into ``AgentExecutor.execute()`` but does not replay prior
outcomes when the client retries with the same ``messageId``. This module
subclasses it so Rasa can:

1. **Cache hit** — return a stored terminal ``Task`` for duplicate
   ``(context_id, message_id)`` without calling ``handle_message()`` again.
2. **In flight** — reject a concurrent duplicate with
   :class:`~rasa.core.a2a_server.errors.A2AMessageInFlightConflict` (HTTP 409
   from :mod:`rasa.core.a2a_server.sanic_app`) while the first request is still
   processing.
3. **Record** — persist terminal outcomes in
   :class:`~rasa.core.a2a_server.a2a_message_cache.A2AMessageCache` after a
   successful turn.

Dedup runs in :meth:`RasaA2ARequestHandler.prepare_message_dispatch` **before**
the SDK's ``_setup_message_execution``, so terminal-task retries with the same
``taskId`` are handled here rather than as ``InvalidParamsError`` inside the SDK.

For streaming, :meth:`build_message_send_stream` performs the same checks
awaitably so Sanic can return 409 before SSE headers are sent.
"""

from __future__ import annotations

from collections.abc import AsyncGenerator
from typing import TYPE_CHECKING, Any, Literal, NoReturn

import structlog
from a2a.server.context import ServerCallContext
from a2a.server.request_handlers import DefaultRequestHandler
from a2a.types import (
    InvalidParamsError,
    Message,
    MessageSendParams,
    Task,
    TaskIdParams,
)
from a2a.utils.errors import ServerError

from rasa.core.a2a_server.a2a_message_cache import (
    A2AMessageCache,
    cache_key_from_dispatch,
    capture_stream_final_task,
    replay_cached_stream,
    should_cache_task,
    task_for_replay_from_params,
)
from rasa.core.a2a_server.errors import (
    A2AMessageInFlightConflict,
    A2APushNotificationUrlRejected,
)

if TYPE_CHECKING:
    from a2a.server.agent_execution import AgentExecutor
    from a2a.server.events import Event, QueueManager
    from a2a.server.tasks import TaskStore

structlogger = structlog.get_logger()


def _raise_push_url_policy_error(exc: A2APushNotificationUrlRejected) -> NoReturn:
    raise ServerError(error=InvalidParamsError(message=exc.message)) from exc


class RasaA2ARequestHandler(DefaultRequestHandler):
    """SDK request handler wired to ``A2AMessageCache``.

    Built by ``RasaA2AAgentExecutor`` and passed to ``JSONRPCHandler`` as
    ``request_handler``.
    """

    def __init__(
        self,
        agent_executor: AgentExecutor,
        task_store: TaskStore,
        message_cache: A2AMessageCache,
        queue_manager: QueueManager | None = None,
        **kwargs: object,
    ) -> None:
        """Initialize the SDK handler with executor, task store, and message cache."""
        super().__init__(
            agent_executor,
            task_store,
            queue_manager=queue_manager,
            **kwargs,
        )
        self._message_cache = message_cache

    @property
    def message_cache(self) -> A2AMessageCache:
        """Terminal-task cache and in-flight registry for ``messageId`` dedup."""
        return self._message_cache

    async def prepare_message_dispatch(
        self,
        params: MessageSendParams,
        context: ServerCallContext | None = None,
    ) -> tuple[Literal["cached", "proceed"], Task | None, tuple[str, str] | None]:
        """Check cache and in-flight state before the SDK starts execution.

        Returns ``("cached", task, cache_key)`` on replay,
        ``("proceed", None, cache_key)`` when processing continues, or
        ``("proceed", None, None)`` when ids are missing.
        Raises :class:`~rasa.core.a2a_server.errors.A2AMessageInFlightConflict`
        if the same key is already in flight.
        """
        cache_key = await self._resolve_cache_key(params, context)
        if cache_key is None:
            return "proceed", None, None

        context_id, message_id = cache_key
        cached = await self._message_cache.get(context_id, message_id)
        if cached is not None:
            structlogger.debug(
                "a2a_server.rasa_a2a_request_handler.cache_hit",
                context_id=context_id,
                message_id=message_id,
            )
            return "cached", cached, cache_key

        if not await self._message_cache.try_begin_in_flight(context_id, message_id):
            raise A2AMessageInFlightConflict(
                context_id=context_id, message_id=message_id
            )
        return "proceed", None, cache_key

    async def on_cancel_task(
        self,
        params: TaskIdParams,
        context: ServerCallContext | None = None,
    ) -> Task | None:
        """Handle `tasks/cancel` and POST the terminal `canceled`
        task if configured."""
        result = await super().on_cancel_task(params, context)
        if isinstance(result, Task) and self._push_sender:
            try:
                await self._push_sender.send_notification(result)
            except A2APushNotificationUrlRejected as exc:
                _raise_push_url_policy_error(exc)
        return result

    def _reject_inline_push_when_disabled(self, params: MessageSendParams) -> None:
        push_config = (
            params.configuration.push_notification_config
            if params.configuration
            else None
        )
        if push_config and not self._push_config_store:
            _raise_push_url_policy_error(
                A2APushNotificationUrlRejected(
                    "Push notifications are disabled on this server."
                )
            )

    async def on_set_task_push_notification_config(
        self,
        params: Any,
        context: ServerCallContext | None = None,
    ) -> Any:
        try:
            return await super().on_set_task_push_notification_config(params, context)
        except A2APushNotificationUrlRejected as exc:
            _raise_push_url_policy_error(exc)

    async def on_message_send(
        self,
        params: MessageSendParams,
        context: ServerCallContext | None = None,
    ) -> Message | Task:
        """Handle ``message/send`` with dedup and terminal-task recording."""
        self._reject_inline_push_when_disabled(params)

        mode, cached, cache_key = await self.prepare_message_dispatch(params, context)
        if mode == "cached" and cached is not None:
            return task_for_replay_from_params(cached, params)

        try:
            result = await super().on_message_send(params, context)
            if cache_key is not None and isinstance(result, Task):
                await self._maybe_record(cache_key, result)
            return result
        except A2APushNotificationUrlRejected as exc:
            _raise_push_url_policy_error(exc)
        finally:
            if cache_key is not None:
                context_id, message_id = cache_key
                await self._message_cache.end_in_flight(context_id, message_id)

    async def build_message_send_stream(
        self,
        params: MessageSendParams,
        context: ServerCallContext | None = None,
    ) -> AsyncGenerator[Event, None]:
        """Return the ``message/stream`` event generator after dedup.

        Await before SSE so cache hits and in-flight conflicts resolve first.
        """
        self._reject_inline_push_when_disabled(params)
        mode, cached, cache_key = await self.prepare_message_dispatch(params, context)
        if mode == "cached" and cached is not None:
            return replay_cached_stream(cached, params)
        return self._message_send_stream_live(params, context, cache_key)

    async def on_message_send_stream(
        self,
        params: MessageSendParams,
        context: ServerCallContext | None = None,
    ) -> AsyncGenerator[Event, None]:
        """SDK ``message/stream`` entry; delegates to ``build_message_send_stream``."""
        stream = await self.build_message_send_stream(params, context)
        async for event in stream:
            yield event

    async def _message_send_stream_live(
        self,
        params: MessageSendParams,
        context: ServerCallContext | None,
        cache_key: tuple[str, str] | None,
    ) -> AsyncGenerator[Event, None]:
        """Run the SDK stream; clear in-flight and record a cacheable final task."""
        final_task: Task | None = None
        try:
            async for event in super().on_message_send_stream(params, context):
                final_task = capture_stream_final_task(final_task, event)
                yield event
            if cache_key is not None and final_task is not None:
                await self._maybe_record(cache_key, final_task)
        except A2APushNotificationUrlRejected as exc:
            _raise_push_url_policy_error(exc)
        finally:
            if cache_key is not None:
                context_id, message_id = cache_key
                await self._message_cache.end_in_flight(context_id, message_id)

    async def _resolve_cache_key(
        self,
        params: MessageSendParams,
        context: ServerCallContext | None = None,
    ) -> tuple[str, str] | None:
        """Return dedup key using message ids and SDK ``RequestContext`` resolution."""
        message = params.message
        params_for_resolution = params.model_copy(deep=True)
        resolution_message = params_for_resolution.message
        task: Task | None = None
        if resolution_message.task_id:
            task = await self.task_store.get(resolution_message.task_id)

        request_context = await self._request_context_builder.build(
            params=params_for_resolution,
            task_id=task.id if task else resolution_message.task_id,
            context_id=resolution_message.context_id
            or (task.context_id if task else None),
            task=task,
            context=context,
        )
        return cache_key_from_dispatch(
            message,
            context_id_fallback=request_context.context_id,
        )

    async def _maybe_record(self, cache_key: tuple[str, str], task: Task) -> None:
        """Persist ``task`` when it is a cacheable terminal outcome."""
        if not should_cache_task(task):
            return
        context_id, message_id = cache_key
        await self._message_cache.record(context_id, message_id, task)
        structlogger.debug(
            "a2a_server.rasa_a2a_request_handler.cache_recorded",
            context_id=context_id,
            message_id=message_id,
            task_state=task.status.state,
        )
